const appWindow = window as AppWindow;
const apiBase = __DAILY_API_URL__.replace(/\/$/, "");
const PRICING_MANAGER_ROLE = keccak256(toUtf8Bytes("PRICING_MANAGER_ROLE"));
const POLICY_MANAGER_ROLE = keccak256(toUtf8Bytes("POLICY_MANAGER_ROLE"));
const REWARD_MANAGER_ROLE = keccak256(toUtf8Bytes("REWARD_MANAGER_ROLE"));
const MODERATOR_ROLE = keccak256(toUtf8Bytes("MODERATOR_ROLE"));
const CATALOG_MANAGER_ROLE = keccak256(toUtf8Bytes("CATALOG_MANAGER_ROLE"));
const abi = ["function annualPrice(uint8) view returns (uint256)", "function hasRole(bytes32,address) view returns (bool)", "function grantRole(bytes32,address)", "function revokeRole(bytes32,address)", "function setAnnualPrice(uint8,uint256)", "function registrationsEnabled() view returns (bool)", "function gracePeriod() view returns (uint64)", "function minCommitmentAge() view returns (uint64)", "function maxCommitmentAge() view returns (uint64)", "function bundleDiscountBps() view returns (uint16)", "function treasury() view returns (address)", "function setRegistrationsEnabled(bool)", "function setGracePeriod(uint64)", "function setCommitmentAges(uint64,uint64)", "function setBundleDiscountBps(uint16)", "function setTreasury(address)"];
const catalogAbi = ["function hasRole(bytes32,address) view returns (bool)", "function catalog(bytes32) view returns (uint8)", "function setCatalog(bytes32,uint8)", "function setCatalogRule(uint256,string,uint8,uint8,bool)", "function setPremiumQuote(bytes32,uint256,uint256,uint64,bool)"];
