const registryAdminAbi = ["function defaultAdmin() view returns (address)", "function pendingDefaultAdmin() view returns (address,uint48)", "function beginDefaultAdminTransfer(address newAdmin)", "function acceptDefaultAdminTransfer()", "function cancelDefaultAdminTransfer()"];
const resolverAdminAbi = ["function hasRole(bytes32,address) view returns (bool)", "function grantRole(bytes32,address)", "function revokeRole(bytes32,address)", "function gatewaySigner() view returns (address)", "function gatewayUrlCount() view returns (uint256)", "function gatewayUrl(uint256) view returns (string)", "function setGatewaySigner(address)", "function addGatewayUrl(string)", "function removeGatewayUrl(uint256)"];
