let connected = "";
let campaignPublicationTargets = new Map<string, { id: string; chainCampaignId: string }>();

async function providerAndSigner() {
  const ethereum = (window as Window & { ethereum?: Eip1193Provider }).ethereum;
  if (!ethereum) throw new Error("MetaMask is required for protected admin actions.");
  const provider = new BrowserProvider(ethereum);
  try { await provider.send("wallet_switchEthereumChain", [{ chainId: "0xaa36a7" }]); } catch (error) { const code = (error as { code?: number }).code; if (code !== 4902) throw error; await provider.send("wallet_addEthereumChain", [{ chainId: "0xaa36a7", chainName: "Sepolia Testnet", nativeCurrency: { name: "Ether", symbol: "ETH", decimals: 18 }, rpcUrls: ["https://ethereum-sepolia-rpc.publicnode.com"], blockExplorerUrls: ["https://sepolia.etherscan.io"] }]); await provider.send("wallet_switchEthereumChain", [{ chainId: "0xaa36a7" }]); }
  const signer = await provider.getSigner(); connected = await signer.getAddress();
  const button = document.querySelector("header .wallet") as HTMLButtonElement | null;
  if (button) button.textContent = short(connected);
  return { provider, signer };
}
async function apiToken(signer: Awaited<ReturnType<typeof providerAndSigner>>["signer"]) {
  if (!apiBase) throw new Error("Daily API URL is not configured for this build."); const address = await signer.getAddress();
  const challenge = await fetch(`${apiBase}/v1/auth/challenge`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ address }) }); if (!challenge.ok) throw new Error("Daily API could not create an admin signature challenge."); const message = (await challenge.json() as { message: string }).message;
  const verification = await fetch(`${apiBase}/v1/auth/verify`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ address, signature: await signer.signMessage(message) }) }); if (!verification.ok) throw new Error("Daily API rejected the admin wallet signature."); return (await verification.json() as { token: string }).token;
}
async function adminRequest(path: string, signer: Awaited<ReturnType<typeof providerAndSigner>>["signer"], init: RequestInit = {}) {
  const headers = new Headers(init.headers); headers.set("authorization", `Bearer ${await apiToken(signer)}`); if (init.body) headers.set("content-type", "application/json"); const response = await fetch(`${apiBase}${path}`, { ...init, headers }); if (!response.ok) throw new Error((await response.json().catch(() => ({ error: "Protected admin request failed." })) as { error?: string }).error ?? "Protected admin request failed."); return response;
}

async function syncLivePrices() {
  try {
    const { provider } = await providerAndSigner();
    const values = await Promise.all(Object.values(SEPOLIA_CONTRACTS.registrars).map(async address => formatEther(await new Contract(address, abi, provider).annualPrice(8))));
    const rows = Array.from(document.querySelectorAll("#tld table tr")).slice(1, 4);
    rows.forEach((row, index) => { const input = row.querySelector("input") as HTMLInputElement | null; if (input) { input.disabled = false; input.value = `${values[index]} ETH`; } });
    const allowed = await new Contract(SEPOLIA_CONTRACTS.registrars.dly, abi, provider).hasRole(PRICING_MANAGER_ROLE, connected);
    await renderRegistrarControls("dly"); notify(allowed ? "Sepolia admin connected. Live prices loaded in ETH." : "Wallet connected, but it lacks the Sepolia pricing-manager role.");
  } catch (error) { notify(error instanceof Error ? error.message : "Unable to load Sepolia pricing."); }
}

function parseUiEth(value: string) {
  const number = value.trim().replace(/\s*(ETH|DLY)\s*$/i, "");
  if (!/^\d+(?:\.\d+)?$/.test(number)) throw new Error("Enter a non-negative ETH amount, for example 0.01 ETH.");
  return parseEther(number);
}

async function savePrices() {
  try {
    const { provider, signer } = await providerAndSigner();
    const rows = Array.from(document.querySelectorAll("#tld table tr")).slice(1, 4);
    if (rows.length !== 3) throw new Error("The sealed TLD pricing rows are unavailable.");
    const canManage = await new Contract(SEPOLIA_CONTRACTS.registrars.dly, abi, provider).hasRole(PRICING_MANAGER_ROLE, connected);
    if (!canManage) throw new Error("Connected wallet is not authorized to change on-chain pricing.");
    for (const [index, tld] of (["dly", "day", "daily"] as const).entries()) {
      const input = rows[index].querySelector("input") as HTMLInputElement | null;
      if (!input) throw new Error(`Missing .${tld} price input.`);
      const tx = await new Contract(SEPOLIA_CONTRACTS.registrars[tld], abi, signer).setAnnualPrice(8, parseUiEth(input.value));
      notify(`Setting .${tld} annual price on Sepolia…`); await tx.wait();
    }
    notify("All three Sepolia TLD standard annual prices were confirmed on-chain.");
  } catch (error) { notify(error instanceof Error ? error.message : "Pricing update failed."); }
}

const wallet = document.querySelector("header .wallet") as HTMLButtonElement | null;
if (wallet) wallet.onclick = event => { event.preventDefault(); void syncLivePrices(); };
const save = document.querySelector("#tld .btn.gold") as HTMLButtonElement | null;
if (save) save.onclick = event => { event.preventDefault(); void savePrices(); };
appWindow.dailyLiveSavePrices = savePrices;

async function renderRegistrarControls(defaultTld: "dly" | "day" | "daily" = "dly") { const pane = document.getElementById("tld"); if (!pane) return; let host = document.getElementById("dailyLiveRegistrarControls"); if (!host) { host = document.createElement("div"); host.id = "dailyLiveRegistrarControls"; host.className = "panel"; pane.append(host); } try { const { provider } = await providerAndSigner(); const selected = ((document.getElementById("dailyLiveControlTld") as HTMLSelectElement | null)?.value ?? defaultTld) as "dly" | "day" | "daily"; const registrar = new Contract(SEPOLIA_CONTRACTS.registrars[selected], abi, provider); const [enabled, grace, minAge, maxAge, discount, treasury] = await Promise.all([registrar.registrationsEnabled(), registrar.gracePeriod(), registrar.minCommitmentAge(), registrar.maxCommitmentAge(), registrar.bundleDiscountBps(), registrar.treasury()]); host.innerHTML = `<div class="head"><div><h3>TLD protocol controls</h3><p>Each change is an explicit on-chain transaction. The connected wallet must hold the relevant limited role or default-admin authority.</p></div><span class="badge purple">On-chain</span></div><div class="grid3"><div class="row"><label>TLD</label><select id="dailyLiveControlTld"><option value="dly" ${selected === "dly" ? "selected" : ""}>.dly</option><option value="day" ${selected === "day" ? "selected" : ""}>.day</option><option value="daily" ${selected === "daily" ? "selected" : ""}>.daily</option></select></div><div class="row"><label>Registration state</label><select id="dailyLiveRegistrationsEnabled"><option value="true" ${enabled ? "selected" : ""}>Enabled</option><option value="false" ${enabled ? "" : "selected"}>Paused</option></select></div><div class="row"><label>Bundle discount (bps)</label><input id="dailyLiveBundleDiscount" type="number" min="0" max="5000" value="${discount}"></div><div class="row"><label>Grace period (days)</label><input id="dailyLiveGraceDays" type="number" min="1" max="365" value="${Number(grace) / 86400}"></div><div class="row"><label>Min commitment (seconds)</label><input id="dailyLiveCommitMin" type="number" min="1" value="${minAge}"></div><div class="row"><label>Max commitment (seconds)</label><input id="dailyLiveCommitMax" type="number" min="2" value="${maxAge}"></div><div class="row"><label>Treasury destination</label><input id="dailyLiveTreasury" value="${treasury}"></div></div><button class="btn ghost" onclick="dailyLiveLoadRegistrarControls()">Load selected TLD</button> <button class="btn gold" onclick="dailyLiveSaveRegistrarControls()">Save protocol controls</button><div class="section"><h3>Limited role management</h3><p>Grant or revoke pricing, catalogue/reserved-name, treasury, and premium-quote roles for this TLD.</p><button class="btn ghost" onclick="dailyLiveGrantRegistrarRole()">Grant role</button> <button class="btn red" onclick="dailyLiveRevokeRegistrarRole()">Revoke role</button></div>`; } catch (error) { host.innerHTML = `<h3>TLD protocol controls unavailable</h3><p>${html(error instanceof Error ? error.message : "Unable to load registrar controls.")}</p>`; } }
const numericControl = (id: string) => { const value = Number((document.getElementById(id) as HTMLInputElement | null)?.value); if (!Number.isInteger(value) || value < 0) throw new Error(`Enter a valid value for ${id}.`); return value; };
appWindow.dailyLiveLoadRegistrarControls = async () => { const tld = ((document.getElementById("dailyLiveControlTld") as HTMLSelectElement | null)?.value ?? "dly") as "dly" | "day" | "daily"; await renderRegistrarControls(tld); };
appWindow.dailyLiveSaveRegistrarControls = async () => { try { const tld = ((document.getElementById("dailyLiveControlTld") as HTMLSelectElement | null)?.value ?? "dly") as "dly" | "day" | "daily"; const { signer } = await providerAndSigner(); const registrar = new Contract(SEPOLIA_CONTRACTS.registrars[tld], abi, signer); const enabled = (document.getElementById("dailyLiveRegistrationsEnabled") as HTMLSelectElement | null)?.value === "true"; const discount = numericControl("dailyLiveBundleDiscount"); const graceDays = numericControl("dailyLiveGraceDays"); const minAge = numericControl("dailyLiveCommitMin"); const maxAge = numericControl("dailyLiveCommitMax"); const treasury = (document.getElementById("dailyLiveTreasury") as HTMLInputElement | null)?.value.trim() ?? ""; if (!/^0x[a-fA-F0-9]{40}$/.test(treasury) || maxAge <= minAge) throw new Error("Use a valid treasury address and a maximum commitment age greater than the minimum."); notify(`Saving .${tld} protocol controls on Sepolia…`); await (await registrar.setRegistrationsEnabled(enabled)).wait(); await (await registrar.setBundleDiscountBps(discount)).wait(); await (await registrar.setGracePeriod(graceDays * 86400)).wait(); await (await registrar.setCommitmentAges(minAge, maxAge)).wait(); await (await registrar.setTreasury(treasury)).wait(); notify(`.${tld} protocol controls confirmed on-chain.`); await renderRegistrarControls(tld); } catch (error) { notify(error instanceof Error ? error.message : "Unable to save TLD protocol controls."); } };

const registrarRoleChoices: Record<string, string> = { "Pricing manager": PRICING_MANAGER_ROLE, "Catalogue and reserved-name manager": CATALOG_MANAGER_ROLE, "Treasury manager": keccak256(toUtf8Bytes("TREASURY_MANAGER_ROLE")), "Premium quote manager": QUOTE_MANAGER_ROLE };
async function changeRegistrarRole(revoke: boolean) {
  const tld = ((document.getElementById("dailyLiveControlTld") as HTMLSelectElement | null)?.value ?? "dly") as "dly" | "day" | "daily";
  const label = window.prompt(`Role to ${revoke ? "revoke" : "grant"}:\n${Object.keys(registrarRoleChoices).join("\n")}`);
  if (!label) return;
  const role = registrarRoleChoices[label]; if (!role) throw new Error("Choose one of the listed registrar roles exactly.");
  const account = window.prompt("Wallet address for this limited role")?.trim() ?? "";
  if (!/^0x[a-fA-F0-9]{40}$/.test(account)) throw new Error("Enter a valid wallet address.");
  const { signer } = await providerAndSigner(); const registrar = new Contract(SEPOLIA_CONTRACTS.registrars[tld], abi, signer);
  notify(`${revoke ? "Revoking" : "Granting"} limited registrar role on Sepolia…`);
  await (await (revoke ? registrar.revokeRole(role, account) : registrar.grantRole(role, account))).wait();
  notify(`Registrar role ${revoke ? "revoked" : "granted"}.`);
}
appWindow.dailyLiveGrantRegistrarRole = async () => { try { await changeRegistrarRole(false); } catch (error) { notify(error instanceof Error ? error.message : "Unable to grant registrar role."); } };
appWindow.dailyLiveRevokeRegistrarRole = async () => { try { await changeRegistrarRole(true); } catch (error) { notify(error instanceof Error ? error.message : "Unable to revoke registrar role."); } };

const catalogCategories: Record<string, number> = { Standard: 0, Premium: 1, Reserved: 2, Official: 3 };
const catalogCategoryName = (value: number) => Object.entries(catalogCategories).find(([, category]) => category === value)?.[0] ?? "Unknown";
function catalogName() { const name = (document.getElementById("dailyLiveCatalogName") as HTMLInputElement | null)?.value.trim().toLowerCase() ?? ""; if (!/^[a-z0-9-]{1,63}\.(dly|day|daily)$/.test(name)) throw new Error("Enter one normalized exact name, for example support.dly."); return name; }
async function renderLiveCatalog() {
  const pane = document.getElementById("catalog"); if (!pane) return;
  pane.innerHTML = `<div class="panel"><div class="head"><div><h3>Standard, premium, reserved and official catalog</h3><p>Exact-label and keyword catalogue rules are written on the selected Sepolia registrar.</p></div><span class="badge purple">On-chain</span></div><div class="row"><label>Upload CSV</label><input id="dailyLiveCatalogCsv" type="file" accept=".csv,text/csv"><button class="btn ghost" onclick="dailyLiveImportCatalog()">Import exact rows</button></div><div class="row"><label>Add name manually</label><input id="dailyLiveCatalogName" placeholder="support.dly"></div><div class="row"><label>Classification</label><select id="dailyLiveCatalogCategory"><option>Standard</option><option>Premium</option><option>Reserved</option><option>Official</option></select></div><button class="btn gold" onclick="dailyLiveSaveCatalog()">Save exact on-chain category</button><button class="btn ghost" style="margin-left:10px" onclick="dailyLiveCheckCatalog()">Check current category</button><div class="section"><h3>Reserved keyword rule</h3><div class="row"><label>Keyword</label><input id="dailyLiveCatalogKeyword" placeholder="daily"><label>Match</label><select id="dailyLiveCatalogMatch"><option value="0">Exact</option><option value="1">Prefix</option><option value="2">Suffix</option><option value="3">Contains</option></select><label>Rule ID</label><input id="dailyLiveCatalogRuleId" type="number" min="0" value="0"></div><button class="btn ghost" onclick="dailyLiveSaveCatalogRule()">Save keyword rule</button></div><div id="dailyLiveCatalogResult" class="section"></div></div>`;
}
async function writeCatalog(name: string, categoryName: string) {
  const category = catalogCategories[categoryName]; if (category === undefined) throw new Error("The deployed registrar supports Standard, Premium, Reserved, and Official exact categories only."); const [, tld] = name.split(".") as [string, "dly" | "day" | "daily"]; const { provider, signer } = await providerAndSigner(); const registrar = new Contract(SEPOLIA_CONTRACTS.registrars[tld], catalogAbi, provider); if (!await registrar.hasRole(CATALOG_MANAGER_ROLE, connected)) throw new Error("Connected wallet is not authorized to change this registrar's catalogue."); notify(`Confirming ${name} catalogue category on Sepolia…`); await (await new Contract(SEPOLIA_CONTRACTS.registrars[tld], catalogAbi, signer).setCatalog(keccak256(toUtf8Bytes(name.split(".")[0])), category)).wait(); return category;
}
appWindow.dailyLiveSaveCatalog = async () => { try { const name = catalogName(); const category = (document.getElementById("dailyLiveCatalogCategory") as HTMLSelectElement | null)?.value ?? ""; await writeCatalog(name, category); notify(`${name} is now ${category} on the Sepolia registrar.`); await appWindow.dailyLiveCheckCatalog?.(); } catch (error) { notify(error instanceof Error ? error.message : "Unable to save on-chain catalogue state."); } };
appWindow.dailyLiveCheckCatalog = async () => { try { const name = catalogName(); const [, tld] = name.split(".") as [string, "dly" | "day" | "daily"]; const { provider } = await providerAndSigner(); const category = Number(await new Contract(SEPOLIA_CONTRACTS.registrars[tld], catalogAbi, provider).catalog(keccak256(toUtf8Bytes(name.split(".")[0])))); const result = document.getElementById("dailyLiveCatalogResult"); if (result) result.innerHTML = `<table class="table"><tr><th>Name</th><th>Current on-chain type</th><th>Action</th></tr><tr><td>${html(name)}</td><td><span class="badge ${category === 1 ? "gold" : category >= 2 ? "red" : "green"}">${catalogCategoryName(category)}</span></td><td>Verified from .${tld} registrar</td></tr></table>`; } catch (error) { notify(error instanceof Error ? error.message : "Unable to read on-chain catalogue state."); } };
appWindow.dailyLiveImportCatalog = async () => { try { const file = (document.getElementById("dailyLiveCatalogCsv") as HTMLInputElement | null)?.files?.[0]; if (!file) throw new Error("Choose a CSV file first."); const rows = (await file.text()).replace(/^\uFEFF/, "").split(/\r?\n/).filter(Boolean); const header = rows.shift()?.trim().toLowerCase(); if (header !== "name,classification") throw new Error("CSV must contain exactly: name,classification"); const parsed = rows.map((line, index) => { const [name, category, extra] = line.split(",").map(value => value.trim()); if (!name || !category || extra || !/^[a-z0-9-]{1,63}\.(dly|day|daily)$/.test(name) || catalogCategories[category] === undefined) throw new Error(`Invalid CSV row ${index + 2}.`); return { name, category }; }); if (!parsed.length || parsed.length > 50) throw new Error("CSV must contain 1 to 50 exact category rows."); for (const row of parsed) await writeCatalog(row.name, row.category); notify(`${parsed.length} exact catalogue categories were confirmed on Sepolia.`); } catch (error) { notify(error instanceof Error ? error.message : "Unable to import on-chain catalogue CSV."); } };
appWindow.dailyLiveSaveCatalogRule = async () => {
  try {
    const keyword = (document.getElementById("dailyLiveCatalogKeyword") as HTMLInputElement | null)?.value.trim().toLowerCase() ?? ""; const matchType = numericControl("dailyLiveCatalogMatch"); const ruleId = numericControl("dailyLiveCatalogRuleId"); const category = catalogCategories[(document.getElementById("dailyLiveCatalogCategory") as HTMLSelectElement | null)?.value ?? ""];
    if (!/^[a-z0-9-]{1,63}$/.test(keyword) || category === undefined || matchType > 3) throw new Error("Enter a normalized keyword, category, and match type.");
    const tld = ((document.getElementById("dailyLiveCatalogName") as HTMLInputElement | null)?.value.trim().split(".")[1] ?? "dly") as "dly" | "day" | "daily";
    const { provider, signer } = await providerAndSigner(); const registrar = new Contract(SEPOLIA_CONTRACTS.registrars[tld], catalogAbi, provider);
    if (!await registrar.hasRole(CATALOG_MANAGER_ROLE, connected)) throw new Error("Connected wallet is not authorized to update keyword policy.");
    notify(`Saving ${keyword} keyword rule on Sepolia…`); await (await new Contract(SEPOLIA_CONTRACTS.registrars[tld], catalogAbi, signer).setCatalogRule(ruleId, keyword, category, matchType, true)).wait(); notify("Keyword policy rule confirmed on-chain.");
  } catch (error) { notify(error instanceof Error ? error.message : "Unable to save keyword policy rule."); }
};
const catalogNavigation = document.querySelector(".sidebtn[data-pane='catalog']") as HTMLButtonElement | null; if (catalogNavigation) catalogNavigation.onclick = event => { event.preventDefault(); document.querySelectorAll(".sidebtn").forEach(button => button.classList.toggle("active", button === catalogNavigation)); document.querySelectorAll(".pane").forEach(pane => pane.classList.toggle("active", pane.id === "catalog")); void renderLiveCatalog(); };

async function renderLiveResolverGateway() { const pane = document.getElementById("resolver"); if (!pane) return; try { const { provider } = await providerAndSigner(); const resolver = new Contract(SEPOLIA_CONTRACTS.resolver, resolverAdminAbi, provider); const count = Number(await resolver.gatewayUrlCount()); const [gatewaySigner, urls] = await Promise.all([resolver.gatewaySigner(), Promise.all(Array.from({ length: count }, (_, index) => resolver.gatewayUrl(index) as Promise<string>))]); const allowed = await resolver.hasRole(GATEWAY_MANAGER_ROLE, connected); pane.innerHTML = `<div class="panel"><div class="head"><div><h3>ERC-3668 resolver gateway</h3><p>Only the Gateway Manager can alter signer or gateway URL configuration. Gateway responses are independently signature-verified by the consuming client.</p></div><span class="badge ${allowed ? "green" : "red"}">${allowed ? "Gateway Manager" : "Read-only"}</span></div><div class="row"><label>Gateway response signer</label><input id="dailyLiveGatewaySigner" value="${gatewaySigner}" placeholder="0x..."></div><button class="btn gold" onclick="dailyLiveSaveGateway()">Save signer</button><div class="row"><label>Add HTTPS gateway URL</label><input id="dailyLiveGatewayUrl" placeholder="https://gateway.example/resolve"></div><button class="btn ghost" onclick="dailyLiveAddGatewayUrl()">Add gateway URL</button><table class="table" style="margin-top:16px"><tr><th>Approved gateway</th><th></th></tr>${urls.map((url, index) => `<tr><td>${html(url)}</td><td><button class="btn red" onclick="dailyLiveRemoveGatewayUrl(${index})">Remove</button></td></tr>`).join("") || "<tr><td colspan=\"2\">No gateway URLs configured.</td></tr>"}</table></div>`; } catch (error) { pane.innerHTML = `<div class="panel"><h3>Resolver gateway unavailable</h3><p>${html(error instanceof Error ? error.message : "Unable to read on-chain resolver gateway state.")}</p></div>`; } }
async function gatewayTransaction(action: "signer" | "add" | "remove", index?: number) { const { provider, signer } = await providerAndSigner(); const resolver = new Contract(SEPOLIA_CONTRACTS.resolver, resolverAdminAbi, provider); if (!await resolver.hasRole(GATEWAY_MANAGER_ROLE, connected)) throw new Error("Connected wallet is not authorized to manage the resolver gateway."); const writable = new Contract(SEPOLIA_CONTRACTS.resolver, resolverAdminAbi, signer); if (action === "signer") { const value = (document.getElementById("dailyLiveGatewaySigner") as HTMLInputElement | null)?.value.trim() ?? ""; if (!/^0x[a-fA-F0-9]{40}$/.test(value)) throw new Error("Enter a valid gateway signer address."); return writable.setGatewaySigner(value); } if (action === "add") { const value = (document.getElementById("dailyLiveGatewayUrl") as HTMLInputElement | null)?.value.trim() ?? ""; if (!/^https:\/\//.test(value)) throw new Error("Gateway URL must use HTTPS."); return writable.addGatewayUrl(value); } return writable.removeGatewayUrl(index); }
appWindow.dailyLiveSaveGateway = async () => { try { notify("Confirming gateway signer update on Sepolia…"); await (await gatewayTransaction("signer")).wait(); notify("Gateway signer updated on-chain."); await renderLiveResolverGateway(); } catch (error) { notify(error instanceof Error ? error.message : "Unable to update gateway signer."); } };
appWindow.dailyLiveAddGatewayUrl = async () => { try { notify("Confirming gateway URL on Sepolia…"); await (await gatewayTransaction("add")).wait(); notify("Gateway URL added on-chain."); await renderLiveResolverGateway(); } catch (error) { notify(error instanceof Error ? error.message : "Unable to add gateway URL."); } };
