type AdminPremiumRequest = { id: string; name: string; applicant_address: string; duration_years: number; reason: string; note: string; evidence_reference?: string | null; status: "submitted" | "quoted" | "rejected"; quoted_registration_wei?: string | null; quoted_renewal_wei?: string | null; quote_expires_at?: string | null };
const html = (value: string) => value.replace(/[&<>"']/g, character => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[character] ?? character);
function premiumRow(request: AdminPremiumRequest) {
  const details = request.status === "submitted"
    ? `<div class="row"><label>Registration ETH</label><input id="dailyLivePremiumReg-${request.id}" value="0.1"></div><div class="row"><label>Renewal ETH</label><input id="dailyLivePremiumRenew-${request.id}" value="0.01"></div><div class="row"><label>Quote expiry</label><input id="dailyLivePremiumExpiry-${request.id}" type="datetime-local"></div><button class="btn gold" onclick="dailyLiveDecidePremium('${request.id}',true)">Create quote</button> <button class="btn red" onclick="dailyLiveDecidePremium('${request.id}',false)">Reject</button>`
    : `<span class="badge ${request.status === "quoted" ? "green" : "red"}">${request.status}</span>${request.status === "quoted" ? `<small style="display:block;margin-top:7px">${formatEther(BigInt(request.quoted_registration_wei ?? "0"))} ETH / ${formatEther(BigInt(request.quoted_renewal_wei ?? "0"))} ETH yearly</small>` : ""}`;
  return `<tr><td><b>${html(request.name)}</b></td><td>${html(short(request.applicant_address))}</td><td>${html(request.reason)}</td><td>${html(request.note)}</td><td>${request.evidence_reference ? "Encrypted evidence reference" : "Not required"}</td><td>${details}</td></tr>`;
}
async function renderLivePremiumRequests() {
  const pane = document.getElementById("quotes"); if (!pane) return;
  try {
    const { signer } = await providerAndSigner(); const response = await adminRequest("/v1/admin/premium-requests", signer); const { requests } = await response.json() as { requests: AdminPremiumRequest[] };
    pane.innerHTML = `<div class="panel"><div class="head"><div><h3>Premium requests and brand claims</h3><p>Submission is free. A protected approval issues an expiring on-chain premium quote; the registrar accepts payment only while that quote is active.</p></div><span class="badge gold">No payment before quote</span></div><table class="table"><tr><th>Name</th><th>Applicant</th><th>Type</th><th>Message</th><th>Evidence</th><th>Action</th></tr>${requests.map(premiumRow).join("") || "<tr><td colspan=\"6\">No protected premium requests are waiting.</td></tr>"}</table></div>`;
  } catch (error) { pane.innerHTML = `<div class="panel"><h3>Premium requests unavailable</h3><p>${html(error instanceof Error ? error.message : "Unable to load protected premium requests.")}</p></div>`; }
}
appWindow.dailyLiveDecidePremium = async (id, approved) => {
  try {
    const { provider, signer } = await providerAndSigner();
    const body = approved ? (() => { const registration = (document.getElementById(`dailyLivePremiumReg-${id}`) as HTMLInputElement | null)?.value.trim() ?? ""; const renewal = (document.getElementById(`dailyLivePremiumRenew-${id}`) as HTMLInputElement | null)?.value.trim() ?? ""; const expiry = (document.getElementById(`dailyLivePremiumExpiry-${id}`) as HTMLInputElement | null)?.value; const expiresAt = expiry ? Math.floor(new Date(expiry).getTime() / 1000) : 0; if (!registration || !renewal || !expiresAt || expiresAt <= Math.floor(Date.now() / 1000)) throw new Error("Enter positive ETH prices and a future quote expiry."); return { approved: true, registrationWei: parseEther(registration).toString(), renewalWei: parseEther(renewal).toString(), expiresAt }; })() : { approved: false };
    if (approved) {
      const requestResponse = await adminRequest("/v1/admin/premium-requests", signer); const { requests } = await requestResponse.json() as { requests: AdminPremiumRequest[] }; const request = requests.find(item => item.id === id);
      if (!request) throw new Error("Premium request was not found."); const [label, tld] = request.name.split(".") as [string, "dly" | "day" | "daily"];
      const registrar = new Contract(SEPOLIA_CONTRACTS.registrars[tld], catalogAbi, provider);
      if (!await registrar.hasRole(QUOTE_MANAGER_ROLE, connected)) throw new Error("Connected wallet is not authorized to issue premium quotes on this registrar.");
      notify(`Confirming premium quote for ${request.name} on Sepolia…`);
      await (await new Contract(SEPOLIA_CONTRACTS.registrars[tld], catalogAbi, signer).setPremiumQuote(keccak256(toUtf8Bytes(label)), body.registrationWei, body.renewalWei, body.expiresAt, true)).wait();
    }
    await adminRequest(`/v1/admin/premium-requests/${id}/decision`, signer, { method: "POST", body: JSON.stringify(body) }); notify(approved ? "Expiring premium quote is issued on-chain and recorded in the protected workflow." : "Premium request rejected through the protected workflow."); await renderLivePremiumRequests();
  } catch (error) { notify(error instanceof Error ? error.message : "Unable to decide premium request."); }
};
const premiumNavigation = document.querySelector(".sidebtn[data-pane='quotes']") as HTMLButtonElement | null; if (premiumNavigation) premiumNavigation.onclick = event => { event.preventDefault(); document.querySelectorAll(".sidebtn").forEach(button => button.classList.toggle("active", button === premiumNavigation)); document.querySelectorAll(".pane").forEach(pane => pane.classList.toggle("active", pane.id === "quotes")); void renderLivePremiumRequests(); };

async function renderLiveMailControls() {
  const pane = document.getElementById("mail"); if (!pane) return;
  try {
    const { signer } = await providerAndSigner();
    const [response, moderationResponse] = await Promise.all([adminRequest("/v1/admin/mail/controls", signer), adminRequest("/v1/admin/mail/moderation", signer)]);
    const { relayPaused } = await response.json() as { relayPaused: boolean }; const moderation = await moderationResponse.json() as { reports: Array<{ sender_address: string; recipient_namehash: string; reason?: string; created_at: string }>; blocks: Array<{ sender_address: string; recipient_namehash: string; created_at: string }> };
    pane.innerHTML = `<div class="panel"><div class="head"><div><h3>Daily Mail relay controls</h3><p>Daily Mail carries ciphertext envelopes only. Pausing stops new envelope acceptance without reading, changing, or exposing mailbox contents.</p></div><span class="badge ${relayPaused ? "red" : "green"}">${relayPaused ? "Paused" : "Accepting envelopes"}</span></div><div class="row"><label>Relay acceptance</label><select id="dailyLiveMailRelayPaused"><option value="false" ${relayPaused ? "" : "selected"}>Accept new encrypted envelopes</option><option value="true" ${relayPaused ? "selected" : ""}>Pause new encrypted envelopes</option></select></div><button class="btn ${relayPaused ? "gold" : "red"}" onclick="dailyLiveSaveMailControls()">${relayPaused ? "Resume relay" : "Pause relay"}</button></div><div class="panel"><div class="head"><div><h3>Privacy-safe moderation</h3><p>Only sender addresses, mailbox hashes, report reasons, and timestamps are shown. Ciphertext and mailbox private keys are never exposed.</p></div><span class="badge purple">${moderation.reports.length} reports · ${moderation.blocks.length} blocks</span></div><table class="table"><tr><th>Sender</th><th>Mailbox hash</th><th>Report reason</th><th>Reported</th></tr>${moderation.reports.map(report => `<tr><td>${html(short(report.sender_address))}</td><td>${html(short(report.recipient_namehash))}</td><td>${html(report.reason ?? "--")}</td><td>${new Date(report.created_at).toLocaleString()}</td></tr>`).join("") || "<tr><td colspan=\"4\">No spam reports.</td></tr>"}</table></div></div>`;
  } catch (error) { pane.innerHTML = `<div class="panel"><h3>Mail controls unavailable</h3><p>${error instanceof Error ? html(error.message) : "Unable to load protected relay controls."}</p></div>`; }
}
appWindow.dailyLiveSaveMailControls = async () => {
  try {
    const relayPaused = (document.getElementById("dailyLiveMailRelayPaused") as HTMLSelectElement | null)?.value === "true";
    const { signer } = await providerAndSigner();
    await adminRequest("/v1/admin/mail/controls", signer, { method: "PUT", body: JSON.stringify({ relayPaused }) });
    notify(relayPaused ? "Daily Mail relay is paused for new encrypted envelopes." : "Daily Mail relay is accepting new encrypted envelopes.");
    await renderLiveMailControls();
  } catch (error) { notify(error instanceof Error ? error.message : "Unable to update Daily Mail relay controls."); }
};
const mailNavigation = document.querySelector(".sidebtn[data-pane='mail']") as HTMLButtonElement | null;
if (mailNavigation) mailNavigation.onclick = event => { event.preventDefault(); document.querySelectorAll(".sidebtn").forEach(button => button.classList.toggle("active", button === mailNavigation)); document.querySelectorAll(".pane").forEach(pane => pane.classList.toggle("active", pane.id === "mail")); void renderLiveMailControls(); };

// Preserve the sealed interface without allowing the simulator's seeded metrics,
// CSV imports, approvals, or moderation buttons to claim that production state
// changed when no protected API/contract operation exists behind them.
const unavailable = "This protected operation is not live yet. It has been disabled instead of simulating a result.";
const adminSafeControl = (element: Element | null) => Boolean(element?.closest("header .wallet,#tld .btn.gold,.sidebtn,.coach,[onclick*='dailyLive'],[onclick*='startTour'],[onclick*='nextTour'],[onclick*='prevTour'],[onclick*='endTour'],[onclick*='toggleCoach']"));
document.addEventListener("click", event => {
  const target = (event.target as Element | null)?.closest("button,a,[role='button']");
  if (!target || adminSafeControl(target)) return;
  event.preventDefault(); event.stopImmediatePropagation(); notify(unavailable);
}, true);
function unavailablePanel(id: string, heading: string, detail: string) {
  const pane = document.getElementById(id);
  if (pane) pane.innerHTML = `<div class="panel"><div class="head"><div><h3>${heading}</h3><p>${detail}</p></div><span class="badge gray">No live data</span></div></div>`;
}
function removeSeededAdminData() {
  Array.from(document.querySelectorAll("#tld table tr")).slice(1, 4).forEach(row => {
    const input = row.querySelector("input") as HTMLInputElement | null;
    if (input) { input.value = ""; input.placeholder = "Connect admin wallet to load live ETH price"; input.disabled = true; }
  });
  unavailablePanel("overview", "Operational data is unavailable", "The dashboard will show only indexed and monitored production state; seeded metrics have been removed.");
  unavailablePanel("catalog", "Name catalog is unavailable", "Catalog changes require the protected on-chain and API workflow.");
  unavailablePanel("resolver", "Resolver gateway is unavailable", "Gateway settings require the signed protected configuration service.");
  unavailablePanel("mail", "Mail controls are unavailable", "No simulated relay, storage, or moderation state is displayed.");
  unavailablePanel("campaigns", "Campaign monitoring is unavailable", "Campaign evidence and moderation require the production campaign service.");
  unavailablePanel("economy", "Campaign economics is unavailable", "No fabricated geography, recipient, or revenue data is displayed.");
  unavailablePanel("transfer", "Admin transfer is unavailable", "The delayed on-chain transfer workflow is not yet wired to this panel.");
  unavailablePanel("monitoring", "Monitoring is unavailable", "Metrics must come from the live indexer, relay, and health checks.");
}
async function loadLiveOverview() {
  const pane = document.getElementById("overview"); if (!pane || !apiBase) return;
  try {
    const response = await fetch(`${apiBase}/health`); const health = await response.json() as { ok: boolean; network?: { name: string; chainId: number }; database?: string; redis?: string };
    pane.innerHTML = `<div class="grid4"><div class="metric"><b>${health.network?.chainId ?? "--"}</b><span>active chain ID</span></div><div class="metric"><b>${health.network?.name ?? "Unavailable"}</b><span>network</span></div><div class="metric"><b>${health.database ?? "unavailable"}</b><span>PostgreSQL</span></div><div class="metric"><b>${health.redis ?? "unavailable"}</b><span>Redis</span></div></div><div class="panel"><h3>Live service health</h3><table class="table"><tr><th>Service</th><th>Status</th></tr><tr><td>API</td><td><span class="badge ${health.ok ? "green" : "red"}">${health.ok ? "Healthy" : "Unavailable"}</span></td></tr><tr><td>Database</td><td>${health.database ?? "unavailable"}</td></tr><tr><td>Redis</td><td>${health.redis ?? "unavailable"}</td></tr></table></div>`;
  } catch { pane.innerHTML = `<div class="panel"><h3>Live service health unavailable</h3><p>The API did not respond. No seeded health data is displayed.</p></div>`; }
}
removeSeededAdminData();
void loadLiveOverview();
